/**
 * `pvoutput_export` pushes instead of pulling: every run uploads new 5-minute status (power and energy of the day) and the daily output of finished days to PVOutput. `solarlog_hosted` creates an FTP account on noonside's own FTP server (SFTPGo) that the Solar-Log uploads its export to (see `upload`); it takes no config and needs `features.hosted_ftp`. It is imported after each upload, not on `poll_interval_s`.
 */
export type DataSourceKind = 'solarlog_remote' | 'solarlog_hosted' | 'pvoutput_export';

/**
 * How a `solarlog_remote` source reaches the server. `ftps` is explicit TLS on the FTP port.
 */
export type SolarLogProtocol = 'ftp' | 'ftps' | 'sftp';

/**
 * Solar-Log HTTP/FTP export: `solarlog_remote` uses the connection fields; `host_key` is SFTP only. `solarlog_hosted` only takes `backfill_history`. `pvoutput_export` uses `pvoutput_system_id` and `api_key`.
 */
export type DataSourceConfig = {
    protocol?: SolarLogProtocol;
    host?: string;
    port?: number;
    username?: string;
    readonly has_password?: boolean;
    directory?: string;
    /**
     * SFTP server public key(s), one per line in authorized_keys or known_hosts (ssh-keyscan) format
     */
    host_key?: string;
    /**
     * Import days_hist/months/years on each run
     */
    backfill_history?: boolean;
    /**
     * PVOutput system ID (sid)
     */
    pvoutput_system_id?: string;
    readonly has_api_key?: boolean;
};

